#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=2;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_vblur;
float4 amzSample_vblur(float2 uv) { return float4(amzt_vblur.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_hblur;
float4 amzSample_hblur(float2 uv) { return float4(amzt_hblur.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_vblur(uv);if(tex==2) return amzSample_hblur(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_strength;
uniform float amzp_rrr;
uniform float2 amzp_higsha;
uniform float2 amzp_satvib;
uniform float amzp_hue;
uniform float2 amzp_position;
uniform float amzp_oalpha;
uniform float amzp_calpha;
uniform float amzp_sshadow;
uniform float amzp_power;
uniform float amzp_alphaa;
uniform float amzp_cblend;
layout(color) uniform half4 amzp_color;
uniform float amzp_alpb;
uniform float amzp_thrs;
uniform float amzp_lowThreshold;
uniform float amzp_highThreshold;
uniform float amzp_feather;
uniform float amzp_iter;


      float2x2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return float2x2(c, -s, s, c);
    }
               float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }

       float4 newLayer( float4 a, float4 b) {
    return a * (1. - b.a) + b;
    }

        void amzRender() {

             float3x3 rgb2yuv = float3x3(
                 0.299,     0.587,    0.114,
                -0.14713,  -0.28886,  0.436,
                 0.615,    -0.51499, -0.10001
            );
             float3x3 yuv2rgb = float3x3(
                1.0,  0.0,      1.13983,
                1.0, -0.39465, -0.58060,
                1.0,  2.03211,  0.0
            );
            float rad = amzp_hue * 0.0174533;
             float3x3 huemat = float3x3(
                1.0,  0.0,       0.0,
                0.0,  cos(rad),  sin(rad),
                0.0,  -sin(rad), cos(rad)
            );

            float4 texColor = amzTexture(0,amzScreenNorm().st);

                float2 satriyaid = amzScreenNorm();


                satriyaid += float2((0.0+(amzp_position.x/15.0)), (0.0+(amzp_position.y/15.0)))*float2(-1.,1.)/500.;











            float4 baseColor;
            float4 compColorr;
            float4 shadow;

            float rr = length(amzp_rrr - amzScreenNorm().st);

            baseColor = amzTexture(0,amzScreenNorm().st)*amzp_calpha;
            compColorr = amzTexture(1, satriyaid);

             float3 rgb = compColorr.rgb ;
             float3 yuv = rgb * rgb2yuv;

            yuv = yuv * huemat; 

            float origSat = min(1.0,length(yuv.yz)*2.5); 
            float2 satUV = yuv.yz * amzp_satvib.y;
            yuv.yz = mix(satUV,yuv.yz,origSat);
            yuv.yz = yuv.yz * (amzp_satvib.x+1.0);
            rgb = yuv * yuv2rgb;

            float4 newComp = float4(rgb, compColorr.a);



            shadow = newComp * (float4(0.,0.,0,1.0) * amzp_higsha.y) * compColorr.a;

            float4 c = shadow + float4(1.)*(1.-shadow.a);

            float4 dblur = float4(newComp.rgb / compColorr.a,1.) * (rr - 0.5);


            float4 targetLuma = dblur ;
            const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (amzp_lowThreshold*(1.0+amzp_feather))-0.0001;
            float lowThresholdA = lowThresholdB-max(amzp_feather,0.00001);
            float highThresholdA = (amzp_highThreshold*(1.0+amzp_feather)-amzp_feather)+0.0001;
            float highThresholdB = highThresholdA+max(amzp_feather,0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            float4 dblurr = targetLuma;
            if ((amzp_thrs>0.5)) {
            dblurr *= lumafx; }


            float4 blendC = float4((dblurr.rgb/dblurr.a)*c.rgb,1.0) * dblurr.a;
            float4 resultfinalx = float4(amzp_color.rgb,dblurr.a) * dblurr.a;



            float4 resultfinal = mix(blendC, resultfinalx, amzp_alpb ) * dblurr.a;
            float4 rrfinal = (amzp_cblend>0.5)? resultfinal : blendC;





            float4 L2 = ((baseColor*amzp_higsha.x) + (rrfinal*amzp_oalpha)) * compColorr.a;
            L2 += baseColor;

            float4 L1 = amzTexture(2, amzScreenNorm().st);
            L1 = float4(float3(0.,0.,0), L1.a);
            L1 *= amzp_alphaa;

            amzOutput = (amzp_sshadow>0.5)? newLayer(L1, L2) : L2;

        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

